update crm_kb_document
title = #{title}, category = #{category}, content_md = #{contentMd}, status = #{status}, metadata = CAST(COALESCE(NULLIF(TRIM(#{metadata,jdbcType=VARCHAR}), ''), '{}') AS jsonb), content_hash = #{contentHash}, index_status = #{indexStatus}, del_flag = #{delFlag}, update_by = #{updateBy}, update_time = #{updateTime},
